// A travel hint only. Special affixes do not enter the reference budget.
export const previousGearLevel=map=>({ruins:70,eclipse:80,celestial:90})[map]||null;
export function equipmentReadiness(player,map,rollGear,gearStatValue,weapon){const level=previousGearLevel(map);if(!level)return null;const defaults={headUpper:'helm',headMiddle:'visor',headLower:'mask',armor:'vest',rightHand:weapon,garment:'cloak',shoes:'boots',accessory1:'chip',accessory2:'ring'};if(player.gear.leftHand?.id==='shield')defaults.leftHand='shield';let weaponRatio=0,armor=0,n=0;for(const [slot,id] of Object.entries(defaults)){const reference=rollGear(id,level,'uncommon',()=>.5),item=player.gear[slot],key=slot==='rightHand'?(reference.affixes.matk?'matk':'atk'):'def',target=gearStatValue(reference,key)||1,ratio=Math.max(0,gearStatValue(item,key)/target);if(slot==='rightHand')weaponRatio=ratio;else{armor+=ratio;n++;}}return {level,ratio:weaponRatio*.4+armor/Math.max(1,n)*.6,target:.65};}
